def generate_settings_ui(repo,output):
 r=SETTINGS_UI;raw=read(repo,r);selected=raw[r['start']:r['end']];assert sha(selected)==r['selectedSha256LF']
 assert raw.count(r['flow'])==1 and sha(r['flow'])==r['flowSha256LF']
 pieces=[];inverse=[];cursor=0
 for e in r['edits']:
  assert e['start']>=cursor and selected[e['start']:e['end']]==e['before']
  pieces.extend((selected[cursor:e['start']],e['after']));inverse.extend((selected[cursor:e['start']],e['before']));cursor=e['end']
 pieces.append(selected[cursor:]);inverse.append(selected[cursor:]);assert ''.join(inverse)==selected
 body=r['header']+r['flow']+''.join(pieces)+r['footer'];assert sha(body)==r['outputSha256LF']
 write(output,r['target'],body)
 return dict(path=r['target'],origin=r['source'],mode='policy-extract',sha256LF=sha(body),generated=True)

def wide(p):
 s=os.path.abspath(p);return Path(s if s.startswith(chr(92)*2+'?'+chr(92))else chr(92)*2+'?'+chr(92)+s)
def sha(t):return hashlib.sha256(t.encode()).hexdigest()
def read(repo,r):
 raw=wide(canonical_source(repo,r['source'])).read_text(encoding='utf8').replace('\r\n','\n')
 assert sha(raw)==r['sourceSha256LF'],r['source'];return raw
def write(output,path,body):
 target=wide(Path(output)/path);target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(body.encode())
def generate(repo,output,standalone=False):
 rows=[]
 for r in RECIPES:
  raw=read(repo,r);lines=raw.splitlines(keepends=True);cursor=0;pieces=[];inverse=[]
  for e in r['edits']:
   assert e['start']==cursor;cursor=e['end'];before=''.join(lines[e['start']:e['end']]);assert sha(before)==e['beforeSha256LF']
   pieces.append(before if e['after']is None else e['after']);inverse.append(before)
  assert cursor==len(lines)and''.join(inverse)==raw
  body=''.join(pieces);assert sha(body)==r['outputSha256LF'];emitted=standalone or r['mode']!='direct'
  if emitted:write(output,r['target'],body)
  rows.append(dict(path=r['target'],origin=r['source'],mode=r['mode'],sha256LF=sha(body),generated=emitted))
 r=SETTINGS;raw=read(repo,r);a=raw.index(r['start']);b=raw.index(r['end'],a);selected=raw[a:b];assert sha(selected)==r['selectedSha256LF'];body=r['header']+selected+r['footer'];assert sha(body)==r['outputSha256LF'];write(output,r['target'],body);rows.append(dict(path=r['target'],origin=r['source'],mode='policy-extract',sha256LF=sha(body),generated=True))
 rows.append(generate_settings_ui(repo,output))
 return rows
